-- Run on a Neon branch after neon/001_schema.sql.
-- Netfly 1.8.0: kids profiles with a maturity limit enforced when playback starts.
-- NOT APPLIED, NOT RUN against Postgres. Apply to staging first.
-- Limits (also in docs): without a PIN, a profile owner can switch a profile's kids flag off or
-- call the Worker without a profile id. This is a family guardrail, not a lock against a determined child.
begin;
alter table public.viewer_profiles add column is_kids boolean not null default false;
grant insert(is_kids) on public.viewer_profiles to authenticated;
grant update(is_kids) on public.viewer_profiles to authenticated;

-- Classification text -> rank. Unknown values (for example "Unrated") rank 99, so kids never see them.
create function private.class_rank(c text) returns int language sql immutable set search_path='' as $$
select case upper(btrim(c)) when 'G' then 0 when 'GE' then 0 when 'PG' then 1 when '13' then 2 when 'PG-13' then 2 when '16' then 3 when '18' then 4 when 'R' then 4 else 99 end $$;
grant execute on function private.class_rank(text) to anonymous,authenticated,netfly_service;

drop function public.start_playback(uuid,uuid,uuid,text,text);
create function public.start_playback(viewer uuid,film uuid,session_key uuid,digest text,country_code text,profile uuid default null) returns uuid language plpgsql security definer set search_path='' as $$ declare result uuid;begin
perform pg_advisory_xact_lock(hashtext(viewer::text));
if not exists(select 1 from auth.sessions where id=session_key and user_id=viewer) or not private.entitled(film,country_code) then raise exception 'Playback unavailable';end if;
if profile is not null then
  if not exists(select 1 from public.viewer_profiles v where v.id=profile and v.account_id=viewer) then raise exception 'Playback unavailable';end if;
  if exists(select 1 from public.viewer_profiles v join public.movies m on m.id=film where v.id=profile and v.is_kids and private.class_rank(m.classification)>1) then raise exception 'Not available on this profile';end if;
end if;
if (select count(*) from public.playback_sessions where user_id=viewer and expires_at>now())>=4 then raise exception 'Active screen limit reached';end if;
insert into public.playback_sessions(user_id,movie_id,auth_session,token_hash,territory,expires_at) values(viewer,film,session_key,digest,country_code,now()+interval '2 minutes') returning id into result;return result; end $$;
revoke all on function public.start_playback(uuid,uuid,uuid,text,text,uuid) from public,anonymous,authenticated;
grant execute on function public.start_playback(uuid,uuid,uuid,text,text,uuid) to netfly_service;
commit;
